items = [
    {"name": "autenticacion", "reach": 1000, "impact": 3, "confidence": 0.8, "effort": 8},
    {"name": "tema personalizado", "reach": 100, "impact": 1, "confidence": 0.9, "effort": 4},
    {"name": "notificaciones", "reach": 500, "impact": 2, "confidence": 0.7, "effort": 5},
]

def rice(item):
    return (item["reach"] * item["impact"] * item["confidence"]) / item["effort"]

for item in items:
    item["rice_score"] = round(rice(item), 1)

ranking = sorted(items, key=lambda i: i["rice_score"], reverse=True)

print("Ranking RICE:")
for pos, item in enumerate(ranking, start=1):
    print(f"  {pos}. {item['name']}: {item['rice_score']}")

moscow = {
    "must": [i["name"] for i in ranking if i["rice_score"] >= 200],
    "should": [i["name"] for i in ranking if 50 <= i["rice_score"] < 200],
    "could": [i["name"] for i in ranking if i["rice_score"] < 50],
}
for categoria, nombres in moscow.items():
    print(f"MoSCoW {categoria}: {nombres}")
